<?php
require __DIR__.'/auth.php';require_module_enabled('import_export');require_capability('imports.manage');require_once __DIR__.'/xlsx_tools.php';
$locations=get_locations($pdo,false);$products=$pdo->query("SELECT p.*,b.name brand_name FROM lager_products p LEFT JOIN lager_brands b ON b.id=p.brand_id ORDER BY p.name")->fetchAll();$stock=$pdo->query('SELECT product_id,location_id,quantity FROM lager_stock')->fetchAll();$sm=[];foreach($stock as $s)$sm[$s['product_id']][$s['location_id']]=(int)$s['quantity'];$res=$pdo->query("SELECT product_id,SUM(quantity) qty FROM lager_reservations WHERE status='reserved' GROUP BY product_id")->fetchAll();$rm=[];foreach($res as $r)$rm[$r['product_id']]=(int)$r['qty'];
$rows=[];$head=['Nummer','Navn','Brand','Kategori','Destilleri','Land','Alc. %','Alder','Årgang','Flaskestørrelse (cl)','Fadtype','Fadnummer','Engrospris','Udsalgspris','Nyhed','Vis i katalog'];foreach($locations as $l)$head[]='Lokation: '.$l['name'];$head[]='Antal i alt';$head[]='Reserveret';$head[]='Disponibelt';$rows[]=$head;
foreach($products as $p){$row=[$p['sku'],$p['name'],$p['brand_name']??'',$p['category']??'',$p['distillery']??'',$p['country']??'',$p['abv']??'',$p['age_text']??'',$p['vintage_year']??'',$p['bottle_size_cl']??'',$p['cask_type']??'',$p['cask_number']??'',$p['wholesale_price']??'',$p['retail_price']??'',$p['is_new']?'Ja':'Nej',$p['show_in_catalog']?'Ja':'Nej'];$total=0;foreach($locations as $l){$q=$sm[$p['id']][$l['id']]??0;$row[]=$q;$total+=$q;}$reserved=$rm[$p['id']]??0;$row[]=$total;$row[]=$reserved;$row[]=$total-$reserved;$rows[]=$row;}
try{xlsx_download($rows,'HSG-lager-'.date('Y-m-d').'.xlsx');}catch(Throwable $e){http_response_code(500);echo h($e->getMessage());}
